"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/tabs.css";
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";
import { cn } from "../../lib/cn";

export function Tabs({ className, ...props }: TabsPrimitive.Root.Props) {
  return <TabsPrimitive.Root className={cn("whatiuse-tabs", className)} {...props} />;
}

export function TabsList({ className, activateOnFocus = true, ...props }: TabsPrimitive.List.Props) {
  return <TabsPrimitive.List className={cn("whatiuse-tabs__list", className)} activateOnFocus={activateOnFocus} {...props} />;
}

export function TabsTrigger({ className, ...props }: TabsPrimitive.Tab.Props) {
  return <TabsPrimitive.Tab className={cn("whatiuse-tabs__trigger", className)} {...props} />;
}

export function TabsContent({ className, ...props }: TabsPrimitive.Panel.Props) {
  return <TabsPrimitive.Panel className={cn("whatiuse-tabs__panel", className)} {...props} />;
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-tabs { display: grid; gap: 16px; }

.whatiuse-tabs__list { display: inline-flex; width: fit-content; height: 30px; align-items: center; gap: 2px; padding: 2px; border: 1px solid var(--whatiuse-border-subtle); border-radius: 6px; background: var(--whatiuse-subtle); }

.whatiuse-tabs__trigger { position: relative; height: 24px; padding: 0 8px; border: 0; border-radius: 4px; outline: 0; background: transparent; color: var(--whatiuse-ink-secondary); font-size: 12.5px; cursor: pointer; }

.whatiuse-tabs__trigger:hover { color: var(--whatiuse-fg-default); }

.whatiuse-tabs__trigger[data-active] { background: var(--whatiuse-control-surface); color: var(--whatiuse-ink); box-shadow: var(--whatiuse-shadow-control), 0 0 0 1px var(--whatiuse-border-subtle); }

.whatiuse-tabs__trigger[data-disabled] { opacity: 0.42; cursor: not-allowed; }

.whatiuse-tabs__trigger:focus-visible { outline: 0; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--whatiuse-focus-control) 48%, transparent); }

.whatiuse-tabs__trigger[data-active]:focus-visible { box-shadow: var(--whatiuse-shadow-control), inset 0 0 0 1px color-mix(in oklch, var(--whatiuse-focus-control) 54%, transparent); }

.whatiuse-tabs__panel { outline: 0; }

@media (forced-colors: active) {
.whatiuse-tabs__list { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }

.whatiuse-tabs__trigger[data-active] { outline: 2px solid Highlight; outline-offset: -2px; }
}

:root[data-theme="dark"] .whatiuse-tabs__trigger:hover { color: var(--whatiuse-ink); }

.whatiuse-tabs__trigger { transition: color var(--whatiuse-hover-duration), background-color var(--whatiuse-hover-duration), box-shadow var(--whatiuse-hover-duration), transform var(--whatiuse-press-duration) var(--whatiuse-ease-out); }
}
